<?php require 'includes/header.php';$s=$_GET['slug']??'';$q=db()->prepare('SELECT * FROM collections WHERE slug=? AND visible=1');$q->execute([$s]);$c=$q->fetch();if(!$c){http_response_code(404);echo '<section class="section"><h2>Koleksiyon bulunamadı</h2></section>';require 'includes/footer.php';exit;}$q=db()->prepare('SELECT * FROM products WHERE collection_id=? AND visible=1 ORDER BY featured DESC,id DESC');$q->execute([$c['id']]);$ps=$q->fetchAll();?><section class="section"><div class="gold">KOLEKSİYON</div><h2><?=e($c['name'])?></h2><p class="muted"><?=e($c['description'])?></p><div class="grid"><?php foreach($ps as $p):?><a class="card" href="product.php?slug=<?=e($p['slug'])?>"><img src="<?=e($p['image']?:'images/hero/hero-placeholder.svg')?>"><div><b><?=e($p['name'])?></b><p class="muted"><?=e($p['code'])?> · <?=e($p['size'])?> · <?=e(stock_label($p['stock']))?></p></div></a><?php endforeach;?></div></section><?php require 'includes/footer.php';?>
